    18→  const [mode, setMode] = useState<'land' | 'bund'>('land');
    19→  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
    20→  const [reports, setReports] = useState<any[]>([]);
    21→  const [loading, setLoading] = useState(true);
    22→  const [opCallsign, setOpCallsign] = useState('');
    23→  const socketRef = useRef(getSocket());
    24→
    25→  const refreshStats = useCallback(async () => {
    26→    if (!id) return;
    27→    try {
    28→      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
    29→      setStats(s);
    30→    } catch {}
    31→  }, [id]);
    32→
    33→  useEffect(() => {
    34→    if (!id) return;
    35→    setLoading(true);
    36→    apiFetch(`/api/v1/exercises/${id}`)
    37→      .then(data => {
    38→        setExercise(data);
    39→        setReports(data.reports || []);
    40→        const firstOp = (data.repeaters || []).find((r: any) => r.operator_callsign);
    41→        if (firstOp) setOpCallsign(firstOp.operator_callsign);
    42→      })
    43→      .catch(() => {})
    44→      .finally(() => setLoading(false));
    45→    refreshStats();
    46→  }, [id, refreshStats]);
    47→
    48→  useEffect(() => {
    49→    if (!id) return;
    50→    const socket = socketRef.current;
    51→    socket.emit('join_exercise', { exercise_id: id });
    52→
    53→    socket.on('report_created', (data: any) => {
    54→      setReports(prev => [data, ...prev]);
    55→      refreshStats();
    56→    });
    57→    socket.on('report_updated', (data: any) => {
    58→      setReports(prev => prev.map(r => r.id === data.id ? data : r));
    59→      refreshStats();
    60→    });
    61→    socket.on('report_deleted', (data: any) => {
    62→      setReports(prev => prev.filter(r => r.id !== data.report_id));
    63→      refreshStats();
    64→    });
    65→
    66→    return () => {
    67→      socket.emit('leave_exercise', { exercise_id: id });
    68→      socket.off('report_created');
    69→      socket.off('report_updated');
    70→      socket.off('report_deleted');
    71→    };
    72→  }, [id, refreshStats]);
    73→
    74→  const handleReportCreated = useCallback((report: any) => {
    75→    setReports(prev => [report, ...prev]);
