   129→          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1 rounded text-sm">
   130→            Einrichten
   131→          </Link>
   132→          <Link to={`/exercises/${id}/reports`} className="bg-red-100 hover:bg-red-200 text-red-800 px-3 py-1 rounded text-sm">
   133→            Auswertung
