import { useState, useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import { apiFetch } from '../services/api';

interface Props {
  value: string;
  onChange: (value: string) => void;
  onSelect: (operator: any) => void;
  autoFocus?: boolean;
  className?: string;
}

export interface CallsignInputRef {
  focus: () => void;
}

const CallsignInput = forwardRef<CallsignInputRef, Props>(({ value, onChange, onSelect, autoFocus, className }, ref) => {
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIdx, setSelectedIdx] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current?.focus(),
  }));

  useEffect(() => {
    if (autoFocus && inputRef.current) inputRef.current.focus();
  }, [autoFocus]);

  const search = (q: string) => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (q.length < 1) { setSuggestions([]); setShowSuggestions(false); return; }
    debounceRef.current = setTimeout(async () => {
      try {
        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
        setSuggestions(results);
        setShowSuggestions(results.length > 0);
        setSelectedIdx(-1);
      } catch {}
    }, 150);
  };

  const handleChange = (val: string) => {
    const upper = val.toUpperCase();
    onChange(upper);
    search(upper);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIdx(prev => Math.min(prev + 1, suggestions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIdx(prev => Math.max(prev - 1, -1));
    } else if (e.key === 'Enter' && selectedIdx >= 0) {
      e.preventDefault();
      selectSuggestion(suggestions[selectedIdx]);
    } else if (e.key === 'Escape') {
      setShowSuggestions(false);
    }
    // Keyboard shortcuts
    if (e.altKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(value + `5/${e.key}`);
    }
    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(`OE${e.key}`);
    }
  };

  const selectSuggestion = (op: any) => {
    onChange(op.callsign);
    onSelect(op);
    setShowSuggestions(false);
    setSuggestions([]);
  };

  return (
    <div className="relative">
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={e => handleChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
        onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
        className={`border border-gray-300 rounded px-2 py-1 font-mono uppercase text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${className || 'w-32'}`}
        placeholder="Rufzeichen"
      />
      {showSuggestions && (
        <div className="absolute z-20 top-full left-0 mt-1 bg-white border rounded shadow-lg max-h-48 overflow-auto w-64">
          {suggestions.map((op, i) => (
            <div
              key={op.id}
              onMouseDown={() => selectSuggestion(op)}
              className={`px-3 py-1.5 cursor-pointer text-sm ${i === selectedIdx ? 'bg-blue-100' : 'hover:bg-gray-100'}`}
            >
              <span className="font-mono font-bold">{op.callsign}</span>
              {op.name && <span className="ml-2 text-gray-500">{op.name}</span>}
              {op.bezirk_code && <span className="ml-1 text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>}
              {op.bundesland_name && <span className="ml-1 text-xs text-gray-400">{op.bundesland_name}</span>}
              {op.total_reports > 0 && <span className="ml-auto text-xs text-blue-500">{op.total_reports} Rap.</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
});

export default CallsignInput;

interface Props {
  stats: {
    totalParticipants: number;
    totalReports: number;
    perRepeater: { short_name: string; count: number }[];
  };
}

export default function RunningTotals({ stats }: Props) {
  return (
    <div className="bg-white rounded-lg shadow-sm px-4 py-2 flex flex-wrap gap-4 text-sm sticky top-0 z-10 border-b">
      <div className="font-medium text-[#1e3a5f]">
        Anwesend: <span className="font-bold">{stats.totalParticipants}</span>
      </div>
      <div className="font-medium text-[#1e3a5f]">
        Rapporte: <span className="font-bold">{stats.totalReports}</span>
      </div>
      <div className="border-l border-gray-300 pl-4 flex flex-wrap gap-3">
        {stats.perRepeater.map(r => (
          <div key={r.short_name} className="text-gray-600">
            {r.short_name}: <span className="font-semibold text-gray-800">{r.count}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../services/api';
import { getSocket } from '../services/socket';
import LandMode from '../components/LandMode';
import BundMode from '../components/BundMode';
import RunningTotals from '../components/RunningTotals';

interface Stats {
  totalParticipants: number;
  totalReports: number;
  perRepeater: { short_name: string; count: number }[];
}

export default function ExercisePage() {
  const { id } = useParams<{ id: string }>();
  const [exercise, setExercise] = useState<any>(null);
  const [mode, setMode] = useState<'land' | 'bund'>('land');
  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
  const [reports, setReports] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [opCallsign, setOpCallsign] = useState('');
  const socketRef = useRef(getSocket());

  const refreshStats = useCallback(async () => {
    if (!id) return;
    try {
      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
      setStats(s);
    } catch {}
  }, [id]);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    apiFetch(`/api/v1/exercises/${id}`)
      .then(data => {
        setExercise(data);
        setReports(data.reports || []);
        const firstOp = (data.repeaters || []).find((r: any) => r.operator_callsign);
        if (firstOp) setOpCallsign(firstOp.operator_callsign);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
    refreshStats();
  }, [id, refreshStats]);

  useEffect(() => {
    if (!id) return;
    const socket = socketRef.current;
    socket.emit('join_exercise', { exercise_id: id });

    socket.on('report_created', (data: any) => {
      setReports(prev => [data, ...prev]);
      refreshStats();
    });
    socket.on('report_updated', (data: any) => {
      setReports(prev => prev.map(r => r.id === data.id ? data : r));
      refreshStats();
    });
    socket.on('report_deleted', (data: any) => {
      setReports(prev => prev.filter(r => r.id !== data.report_id));
      refreshStats();
    });

    return () => {
      socket.emit('leave_exercise', { exercise_id: id });
      socket.off('report_created');
      socket.off('report_updated');
      socket.off('report_deleted');
    };
  }, [id, refreshStats]);

  const handleReportCreated = useCallback((report: any) => {
    setReports(prev => [report, ...prev]);
    socketRef.current.emit('report_created', { ...report, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const handleReportUpdated = useCallback((report: any) => {
    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    socketRef.current.emit('report_updated', { ...report, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const handleReportDeleted = useCallback((reportId: number) => {
    setReports(prev => prev.filter(r => r.id !== reportId));
    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const updateOpCallsign = async (val: string) => {
    const reps = exercise?.repeaters || [];
    for (const r of reps) {
      await apiFetch(`/api/v1/exercises/${id}/repeaters/${r.repeater_id}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    setExercise((prev: any) => prev ? {
      ...prev,
      repeaters: prev.repeaters?.map((r: any) => ({ ...r, operator_callsign: val || null })),
    } : null);
  };

  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
