        </div>
        <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm flex-shrink-0">
          Zurück
        </Link>
      </div>

      {stats && (
        <>
          {/* Summary cards */}
