     1→import { useState, useEffect, useRef, type FormEvent } from 'react';
     2→import { apiFetch, getOrCreateOperator } from '../services/api';
     3→import CallsignInput, { type CallsignInputRef } from './CallsignInput';
     4→
     5→const BUNDESLAND_NAMES: Record<string, string> = {
     6→  '01': 'OE1 Wien',
     7→  '02': 'OE2 Salzburg',
     8→  '03': 'OE3 Niederösterreich',
     9→  '04': 'OE4 Burgenland',
    10→  '05': 'OE5 Oberösterreich',
    11→  '06': 'OE6 Steiermark',
    12→  '07': 'OE7 Tirol',
    13→  '08': 'OE8 Kärnten',
    14→  '09': 'OE9 Vorarlberg',
    15→  '10': 'Slowenien',
    16→};
    17→
    18→interface Props {
    19→  exerciseId: string;
    20→  repeaters: any[];
    21→  reports: any[];
    22→  onReportCreated: (report: any) => void;
    23→  onReportUpdated: (report: any) => void;
    24→  onReportDeleted: (reportId: number) => void;
    25→}
    26→
    27→interface EntryForm {
    28→  callsign: string;
    29→  operator: any;
    30→  rapport: string;
    31→  notes: string;
    32→}
    33→
    34→export default function LandMode({ exerciseId, repeaters, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    35→  const [collapsedReps, setCollapsedReps] = useState<Set<number>>(new Set());
    36→  const [opCallsigns, setOpCallsigns] = useState<Record<number, string>>({});
    37→  const [bezirke, setBezirke] = useState<any[]>([]);
    38→  const [editingId, setEditingId] = useState<number | null>(null);
    39→  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
    40→
    41→  // Load bezirke + OP callsigns
    42→  useEffect(() => {
    43→    Promise.all([
    44→      apiFetch('/api/v1/reference/bezirke'),
    45→      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    46→    ]).then(([bz, exReps]) => {
    47→      setBezirke(bz);
    48→      const ops: Record<number, string> = {};
    49→      for (const er of exReps) {
    50→        if (er.operator_callsign) {
    51→          ops[er.repeater_id] = er.operator_callsign;
    52→        }
    53→      }
    54→      setOpCallsigns(ops);
    55→    }).catch(() => {});
    56→  }, [exerciseId]);
    57→
    58→  // Group repeaters by Bundesland — exclude linked repeaters (those belong to BundMode)
    59→  const repeatersByBl: Record<string, any[]> = {};
    60→  const simplexRepeaters: any[] = [];
    61→  for (const r of repeaters) {
    62→    if (r.is_linked) continue;
    63→    if (r.type === 'simplex') {
    64→      simplexRepeaters.push(r);
    65→    } else {
    66→      const blCode = r.bundesland_code || '_other';
    67→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    68→      repeatersByBl[blCode].push(r);
    69→    }
    70→  }
    71→
    72→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    73→    if (a === '_other') return 1;
    74→    if (b === '_other') return -1;
    75→    return a.localeCompare(b);
    76→  });
    77→
    78→  const toggleRepeater = (repId: number) => {
    79→    setCollapsedReps(prev => {
    80→      const next = new Set(prev);
    81→      if (next.has(repId)) next.delete(repId); else next.add(repId);
    82→      return next;
    83→    });
    84→  };
    85→
    86→  const saveOpCallsign = async (repeaterId: number, val: string) => {
    87→    try {
    88→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
    89→        method: 'POST',
    90→        body: JSON.stringify({ repeater_id: repeaterId, operator_callsign: val || null }),
    91→      });
    92→    } catch {
    93→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repeaterId}`, {
    94→        method: 'PATCH',
    95→        body: JSON.stringify({ operator_callsign: val || null }),
    96→      });
    97→    }
    98→  };
    99→
   100→  const parseRapport = (raw: string) => {
   101→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
   102→    if (!match) return { readability: null, strength: null, db_over_s9: null };
   103→    return {
   104→      readability: parseInt(match[1]),
   105→      strength: parseInt(match[2]),
   106→      db_over_s9: match[3]?.trim() || null,
   107→    };
   108→  };
   109→
   110→  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
   111→    try {
   112→      const operator = await getOrCreateOperator(form.callsign, form.operator);
   113→      if (!operator) return;
   114→
   115→      // Set operator's bezirk_code to match the row they were entered in
   116→      if (bezirkCode && bezirkCode !== '??') {
   117→        apiFetch(`/api/v1/operators/${operator.id}`, {
   118→          method: 'PATCH',
   119→          body: JSON.stringify({ bezirk_code: bezirkCode }),
   120→        }).catch(() => {});
   121→      }
   122→
   123→      const parsed = parseRapport(form.rapport);
   124→
   125→      try {
   126→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   127→          method: 'POST',
   128→          body: JSON.stringify({
   129→            operator_id: operator.id,
   130→            repeater_id: repeaterId,
   131→            ...parsed,
   132→            notes: form.notes || null,
   133→          }),
   134→        });
   135→        // Force bezirk_code on report so it shows in the correct row immediately
   136→        if (bezirkCode && bezirkCode !== '??') report.bezirk_code = bezirkCode;
   137→        onReportCreated(report);
   138→      } catch (err: any) {
   139→        if (err.message?.includes('existiert')) {
   140→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   141→          if (existing) {
   142→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   143→              method: 'PATCH',
   144→              body: JSON.stringify({ ...parsed, notes: form.notes || null }),
   145→            });
   146→            if (bezirkCode && bezirkCode !== '??') updated.bezirk_code = bezirkCode;
   147→            onReportUpdated(updated);
   148→          }
   149→        }
   150→      }
   151→    } catch {}
   152→  };
   153→
   154→  const handleEdit = (report: any) => {
   155→    setEditingId(report.id);
   156→    setEditForm({
   157→      callsign: report.callsign,
   158→      operator: { id: report.operator_id, callsign: report.callsign },
   159→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   160→      notes: report.notes || '',
   161→    });
   162→  };
   163→
   164→  const handleUpdate = async () => {
   165→    if (!editingId) return;
   166→    const parsed = parseRapport(editForm.rapport);
   167→    try {
   168→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   169→        method: 'PATCH',
   170→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
   171→      });
   172→      onReportUpdated(updated);
   173→      setEditingId(null);
   174→    } catch {}
   175→  };
   176→
   177→  const handleDelete = async (reportId: number) => {
   178→    if (!confirm('Rapport löschen?')) return;
   179→    try {
   180→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   181→      onReportDeleted(reportId);
   182→    } catch {}
   183→  };
   184→
   185→  const renderRepeaterCard = (rep: any) => {
   186→    const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
   187→    const reportCount = repReports.filter(r => r.readability).length;
   188→    const isCollapsed = collapsedReps.has(rep.repeater_id);
   189→    const repBezirke = bezirke.filter(b => b.bundesland_code === rep.bundesland_code);
   190→
   191→    return (
   192→      <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm">
   193→        <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
   194→          <div
   195→            onClick={() => toggleRepeater(rep.repeater_id)}
   196→            className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
   197→          >
   198→            <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   199→            <span className="font-medium text-xs sm:text-sm truncate">{rep.short_name}</span>
   200→            <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
   201→            {rep.frequency_mhz && (
   202→              <span className="text-xs text-gray-400 hidden sm:inline">{rep.frequency_mhz} MHz</span>
   203→            )}
   204→            {rep.offset_mhz && (
   205→              <span className="text-xs text-gray-400 hidden md:inline">({rep.offset_mhz > 0 ? '+' : ''}{rep.offset_mhz})</span>
   206→            )}
   207→            {rep.ctcss_hz && (
   208→              <span className="text-xs text-gray-400 hidden md:inline">CTCSS {rep.ctcss_hz}</span>
   209→            )}
   210→          </div>
   211→          <div className="flex items-center gap-1.5" onClick={e => e.stopPropagation()}>
   212→            <label className="text-xs text-gray-500">OP:</label>
   213→            <input
   214→              type="text"
   215→              value={opCallsigns[rep.repeater_id] || ''}
   216→              onChange={e => setOpCallsigns(prev => ({ ...prev, [rep.repeater_id]: e.target.value.toUpperCase() }))}
   217→              onBlur={e => saveOpCallsign(rep.repeater_id, e.target.value.toUpperCase())}
   218→              placeholder="Rufz."
   219→              className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500"
   220→            />
   221→          </div>
   222→        </div>
   223→
   224→        {!isCollapsed && (
   225→          <div className="divide-y divide-gray-100">
   226→            {repBezirke.map(bz => {
   227→              const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
   228→              return (
   229→                <BezirkRow
   230→                  key={bz.code}
   231→                  bezirk={bz}
   232→                  reports={bzReports}
   233→                  repeaterId={rep.repeater_id}
   234→                  onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
   235→                  onEdit={handleEdit}
   236→                  onDelete={handleDelete}
   237→                  editingId={editingId}
   238→                  editForm={editForm}
   239→                  onEditChange={setEditForm}
   240→                  onEditSave={handleUpdate}
   241→                  onEditCancel={() => setEditingId(null)}
   242→                />
   243→              );
   244→            })}
   245→            {/* Reports without matching bezirk */}
   246→            {(() => {
   247→              const bzCodes = new Set(repBezirke.map(b => b.code));
   248→              const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   249→              if (unassigned.length === 0) return null;
   250→              return (
   251→                <div className="px-3 py-1.5">
   252→                  <table className="w-full text-xs mb-1">
   253→                    <tbody>
   254→                      {unassigned.map((r, idx) => (
   255→                        <tr key={r.id} className="hover:bg-blue-50 group">
   256→                          {editingId === r.id ? (
   257→                            <td colSpan={5} className="py-0.5">
   258→                              <div className="flex items-center gap-1 bg-blue-50 rounded p-1">
   259→                                <span className="font-mono font-medium">{r.callsign}</span>
   260→                                <input value={editForm.rapport} onChange={e => setEditForm({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" autoFocus />
   261→                                <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   262→                                <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   263→                                <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   264→                              </div>
   265→                            </td>
   266→                          ) : (
   267→                            <>
   268→                              <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   269→                              <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => handleEdit(r)}>{r.callsign}</td>
   270→                              <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   271→                                {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   272→                              </td>
   273→                              <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   274→                              <td className="py-0.5 w-4">
   275→                                <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   276→                              </td>
   277→                            </>
   278→                          )}
   279→                        </tr>
   280→                      ))}
   281→                    </tbody>
   282→                  </table>
   283→                </div>
   284→              );
   285→            })()}
   286→          </div>
   287→        )}
   288→      </div>
   289→    );
   290→  };
   291→
   292→  return (
   293→    <div className="space-y-2">
   294→      {sortedBlCodes.map(blCode => {
   295→        const blReps = repeatersByBl[blCode];
   296→        const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
   297→        return (
   298→          <div key={blCode}>
   299→            <div className="px-1 mb-1 mt-2">
   300→              <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
   301→            </div>
   302→            <div className="space-y-2">
   303→              {blReps.map(rep => renderRepeaterCard(rep))}
   304→            </div>
   305→          </div>
   306→        );
   307→      })}
   308→
   309→      {simplexRepeaters.length > 0 && (
   310→        <div>
   311→          <div className="px-1 mb-1 mt-2">
   312→            <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Simplex</span>
   313→          </div>
   314→          <div className="space-y-2">
   315→            {simplexRepeaters.map(rep => renderRepeaterCard(rep))}
   316→          </div>
   317→        </div>
   318→      )}
   319→    </div>
   320→  );
   321→}
   322→
   323→interface BezirkRowProps {
   324→  bezirk: any;
   325→  reports: any[];
   326→  repeaterId: number;
   327→  onSubmit: (form: EntryForm) => void;
   328→  onEdit: (report: any) => void;
   329→  onDelete: (id: number) => void;
   330→  editingId: number | null;
   331→  editForm: EntryForm;
   332→  onEditChange: (form: EntryForm) => void;
   333→  onEditSave: () => void;
   334→  onEditCancel: () => void;
   335→}
   336→
   337→function BezirkRow({ bezirk, reports, repeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
   338→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '' });
   339→  const callsignRef = useRef<CallsignInputRef>(null);
   340→
   341→  const handleSubmit = (e: FormEvent) => {
   342→    e.preventDefault();
   343→    if (!form.callsign && !form.operator) return;
   344→    onSubmit(form);
   345→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '' });
   346→    setTimeout(() => callsignRef.current?.focus(), 50);
   347→  };
   348→
   349→  return (
   350→    <div className="px-2 sm:px-3 py-1.5">
   351→      {bezirk.code !== '??' && (
   352→        <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   353→          <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   354→            {bezirk.code}
   355→          </span>
   356→          <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   357→          {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   358→        </div>
   359→      )}
   360→
   361→      {reports.length > 0 && (
   362→        <table className="w-full text-xs mb-1">
   363→          <tbody>
   364→            {reports.map((r, idx) => (
   365→              <tr key={r.id} className="hover:bg-blue-50 group">
   366→                {editingId === r.id ? (
   367→                  <td colSpan={5} className="py-0.5">
   368→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap">
   369→                      <span className="font-mono font-medium">{r.callsign}</span>
   370→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   371→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   372→                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
   373→                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
   374→                    </div>
   375→                  </td>
   376→                ) : (
   377→                  <>
   378→                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   379→                    <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => onEdit(r)}>{r.callsign}</td>
   380→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   381→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   382→                    </td>
   383→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   384→                    <td className="py-0.5 w-4">
   385→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   386→                    </td>
   387→                  </>
   388→                )}
   389→              </tr>
   390→            ))}
   391→          </tbody>
   392→        </table>
   393→      )}
   394→
   395→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   396→        <CallsignInput
   397→          ref={callsignRef}
   398→          value={form.callsign}
   399→          onChange={v => setForm(f => ({ ...f, callsign: v }))}
   400→          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign }))}
   401→          className="w-24 sm:w-28"
   402→        />
   403→        <input
   404→          type="text"
   405→          value={form.rapport}
   406→          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
   407→          placeholder="5/9"
   408→          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   409→          onKeyDown={e => {
   410→            if (e.altKey && e.key >= '1' && e.key <= '9') {
   411→              e.preventDefault();
   412→              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
   413→            }
   414→          }}
   415→        />
   416→        <input
   417→          type="text"
