            Frequenzen
          </button>
          <button
            onClick={() => setMode('bund')}
            className={`flex-1 sm:flex-none px-3 sm:px-4 py-1.5 rounded text-xs sm:text-sm font-medium ${mode === 'bund' ? 'bg-[#1e3a5f] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
          >
            OE-Link
          </button>
        </div>
      )}

      {mode === 'land' || !oeLinkEnabled ? (
        <LandMode
          exerciseId={id!}
          repeaters={exercise.repeaters || []}
          reports={reports}
          onReportCreated={handleReportCreated}
          onReportUpdated={handleReportUpdated}
          onReportDeleted={handleReportDeleted}
        />
      ) : (
        <BundMode
          exerciseId={id!}
          reports={reports}
          onReportCreated={handleReportCreated}
          onReportUpdated={handleReportUpdated}
          onReportDeleted={handleReportDeleted}
        />
      )}
    </div>
  );
}

input.command:
ssh host-node-01 "docker exec bosarsalog node -e \"
const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// Get test exercises
const exercises = db.prepare(\\\"SELECT id, name, date, oe_link_enabled FROM exercises WHERE name LIKE '%Testdaten%' ORDER BY date\\\").all();
console.log('Test exercises:');
exercises.forEach(e => console.log(JSON.stringify(e)));

// Get all repeaters
const reps = db.prepare(\\\"SELECT id, short_name, bundesland_code, type, is_linked, frequency_mhz FROM repeaters ORDER BY sort_order\\\").all();
console.log('\\nRepeaters:');
reps.forEach(r => console.log(JSON.stringify(r)));

// Get exercise_repeaters for test exercises
console.log('\\nExercise repeaters:');
for (const ex of exercises) {
  const er = db.prepare(\\\"SELECT er.repeater_id, r.short_name FROM exercise_repeaters er JOIN repeaters r ON r.id = er.repeater_id WHERE er.exercise_id = ?\\\").all(ex.id);
  console.log(ex.name + ': ' + er.map(r => r.short_name).join(', '));
}

// Current report counts
console.log('\\nCurrent report counts:');
for (const ex of exercises) {
  const c = db.prepare(\\\"SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ?\\\").get(ex.id);
  console.log(ex.name + ': ' + c.c);
}
\""

