import openpyxl, json, glob

f = glob.glob("/home/achildrenmile/Downloads/2026*BOS*xlsx")[0]
wb = openpyxl.load_workbook(f, data_only=True)

ws = wb["20260104"]

# Get repeater headers (row 1, cols P onwards = index 15+)
repeater_headers = {}
for col_idx in range(15, min(ws.max_column, 30)):
    val = ws.cell(row=1, column=col_idx+1).value
    if val:
        repeater_headers[col_idx] = str(val)[:60]

print("Repeater columns:")
for k, v in repeater_headers.items():
    print(f"  {k}: {v}")

operators = []
for row_idx in range(2, ws.max_row+1):
    anwesend = ws.cell(row=row_idx, column=4).value
    if anwesend != 1:
        continue

    callsign = ws.cell(row=row_idx, column=1).value
    suffix = ws.cell(row=row_idx, column=2).value
    name = ws.cell(row=row_idx, column=10).value
    qth = ws.cell(row=row_idx, column=11).value
    bezirk = ws.cell(row=row_idx, column=12).value
    bl = ws.cell(row=row_idx, column=13).value

    if not callsign:
        continue

    reports = []
    for col_idx, header in repeater_headers.items():
        val = ws.cell(row=row_idx, column=col_idx+1).value
        if val and str(val).strip():
            reports.append({"col": col_idx, "header": header, "rapport": str(val).strip()})

    if reports:
        bl_code = str(bl).split("-")[0].strip() if bl else None
        suf = str(suffix).strip() if suffix else None
        if suf in ["0", "None", ""]:
            suf = None
        operators.append({
            "callsign": str(callsign).strip(),
            "suffix": suf,
            "name": str(name).strip() if name else None,
            "bezirk": str(bezirk).strip() if bezirk else None,
            "bundesland": bl_code,
            "reports": reports
        })

print(f"\nTotal operators with reports: {len(operators)}")
print("\nAll operators:")
for op in operators:
    suf = ""
    if op["suffix"]:
        s = op["suffix"]
        if s in ["p", "P"]:
            suf = "/P"
        elif s in ["m", "M", "mobil"]:
            suf = "/M"
        elif s.startswith("/"):
            suf = s
        else:
            suf = "/" + s.upper()
    reps = "; ".join([r["rapport"] for r in op["reports"]])
    print(f"  {op['callsign']}{suf} [{op['bezirk']}] BL={op['bundesland']}: {reps}")

all_rapports = set()
for op in operators:
    for r in op["reports"]:
        all_rapports.add(r["rapport"])
print(f"\nUnique rapport values ({len(all_rapports)}):")
for r in sorted(all_rapports):
    print(f"  {r}")

# Save to JSON
with open("/tmp/qso_data.json", "w") as f:
    json.dump({"operators": operators, "repeater_headers": repeater_headers}, f, ensure_ascii=False, indent=2)
print("\nSaved to /tmp/qso_data.json")

