// ===== STEP 5: Insert all QSO data =====
function insertQsos(exerciseId, qsos) {
  let reportCount = 0;
  let opCount = 0;
  for (const q of qsos) {
    const op = getOrCreateOperator(q.call, q.name, q.bz, q.bl);
    opCount++;
    for (const [repKey, r, s, db_over, notes] of q.reps.map(r => [r[0], parseInt(r[1].split('/')[0]), parseInt(r[1].split('/')[1]), r[2], r[3]])) {
      const rep = repMap[repKey];
      if (!rep) {
        console.log(`  WARNING: repeater key "${repKey}" not mapped`);
        continue;
      }
      addReport(exerciseId, op.id, rep.id, r, s, db_over, notes);
      reportCount++;
    }
  }
  return { opCount, reportCount };
}

