const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// ===== STEP 1: Clear all existing reports & attendance from test exercises =====
const testExercises = db.prepare("SELECT id, name, date, oe_link_enabled FROM exercises WHERE name LIKE '%Testdaten%' ORDER BY date").all();
console.log('Test exercises:');
for (const ex of testExercises) {
  db.prepare('DELETE FROM signal_reports WHERE exercise_id = ?').run(ex.id);
  db.prepare('DELETE FROM exercise_attendance WHERE exercise_id = ?').run(ex.id);
  console.log(`  Cleared: ${ex.name} (${ex.date})`);
}

// ===== STEP 2: Set up repeaters for Krisenkommunikationsübungen =====
const krisenEx = testExercises.filter(e => e.name.includes('Krisenkommunikation'));
const notfunkEx = testExercises.filter(e => e.name.includes('Notfunk'));

// Repeater mapping by short_name
const allReps = db.prepare('SELECT * FROM repeaters').all();
const repByName = {};
for (const r of allReps) repByName[r.short_name] = r;

// Configure Krisenkommunikationsübungen with realistic repeater set
const krisenRepeaters = [
  'Gerlitzen 2m',          // OE8 - main 2m
  'Gerlitzen 70cm',        // OE8 - main 70cm
  'Magdalensberg linked',  // OE8 - OE-Link (linked: Magdalensberg, HK, Schöckl, Gaisberg)
  'Buschberg 70cm',        // OE3
  'Goldeck 2m',            // OE8
  'Dobratsch 23cm',        // OE8
  'Direkte 145.300',       // simplex
  'Direkte 145.525',       // simplex
  'Zirbitzkogel 70cm',     // OE6
  'Struška 70cm',          // OE10/SLO
  'Hochstuhl 70cm',        // OE10/SLO
];

for (const ex of krisenEx) {
  // Clear existing repeater config
  db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ?').run(ex.id);
  for (const name of krisenRepeaters) {
    const rep = repByName[name];
    if (rep) {
      db.prepare('INSERT OR IGNORE INTO exercise_repeaters (exercise_id, repeater_id) VALUES (?, ?)').run(ex.id, rep.id);
    } else {
      console.log(`  WARNING: repeater "${name}" not found`);
    }
  }
  console.log(`  Configured ${krisenRepeaters.length} repeaters for ${ex.name}`);
}

// Set organisator for exercises
db.prepare("UPDATE exercises SET organisator = 'OE8SSR' WHERE id = ?").run(krisenEx[0]?.id);
db.prepare("UPDATE exercises SET organisator = 'OE8GWQ' WHERE id = ?").run(krisenEx[1]?.id);
db.prepare("UPDATE exercises SET organisator = 'OE3EGH' WHERE id = ?").run(notfunkEx[0]?.id);
db.prepare("UPDATE exercises SET organisator = 'OE8OPT' WHERE id = ?").run(notfunkEx[1]?.id);

// ===== STEP 3: Helper functions =====
function getOrCreateOperator(callsign, name, bezirk, bundesland) {
  let op = db.prepare('SELECT * FROM operators WHERE callsign = ?').get(callsign);
  if (!op) {
    db.prepare('INSERT INTO operators (callsign, name, bezirk_code, bundesland_code) VALUES (?, ?, ?, ?)').run(callsign, name, bezirk, bundesland);
    op = db.prepare('SELECT * FROM operators WHERE callsign = ?').get(callsign);
  } else {
    // Update bezirk/bundesland if missing
    if (!op.bezirk_code && bezirk) {
      db.prepare('UPDATE operators SET bezirk_code = ? WHERE id = ?').run(bezirk, op.id);
    }
    if (!op.bundesland_code && bundesland) {
      db.prepare('UPDATE operators SET bundesland_code = ? WHERE id = ?').run(bundesland, op.id);
    }
    if (!op.name && name) {
      db.prepare('UPDATE operators SET name = ? WHERE id = ?').run(name, op.id);
    }
  }
  return op;
}

function addReport(exerciseId, operatorId, repeaterId, readability, strength, dbOverS9, notes) {
  try {
    db.prepare(`INSERT INTO signal_reports (exercise_id, operator_id, repeater_id, readability, strength, db_over_s9, notes, entered_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, 'admin')`).run(exerciseId, operatorId, repeaterId, readability, strength, dbOverS9 || null, notes || null);
    db.prepare('INSERT OR IGNORE INTO exercise_attendance (exercise_id, operator_id, entered_by) VALUES (?, ?, ?)').run(exerciseId, operatorId, 'admin');
  } catch (e) {
    // Ignore duplicates
  }
}

function parseRapport(raw) {
  // Parse "5/9+30 HK" -> { r: 5, s: 9, db: "+30", notes: "HK" }
  const m = raw.match(/^(\d)\/(\d)(\+\d+|[\+]+)?\s*(.*)?$/);
  if (!m) return { r: 5, s: 9, db: null, notes: raw };
  let db_val = m[3] || null;
  if (db_val === '++') db_val = '+20';
  if (db_val === '+') db_val = '+10';
  return { r: parseInt(m[1]), s: parseInt(m[2]), db: db_val, notes: m[4] || null };
}

