const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// 1. Fix incorrect is_capital flags (Statutarstädte that are NOT Landeshauptstädte)
const fixCapitals = [
  { code: 'KS', name: 'Krems Stadt' },      // NÖ - Statutarstadt, not capital
  { code: 'SE', name: 'Steyr Stadt' },       // OÖ - Statutarstadt, not capital
  { code: 'WE', name: 'Wels' },              // OÖ - Statutarstadt, not capital
  { code: 'VI', name: 'Villach Stadt' },      // Kärnten - Statutarstadt, not capital
];

for (const b of fixCapitals) {
  db.prepare('UPDATE bezirke SET is_capital = 0 WHERE code = ?').run(b.code);
  console.log('Fixed is_capital=0 for ' + b.code + ' (' + b.name + ')');
}

// 2. Add missing Landeshauptstädte
const missingCapitals = [
  { code: 'E',  name: 'Eisenstadt',      bundesland_code: '04', is_capital: 1 },
  { code: 'L',  name: 'Linz Stadt',      bundesland_code: '05', is_capital: 1 },
  { code: 'G',  name: 'Graz Stadt',      bundesland_code: '06', is_capital: 1 },
  { code: 'I',  name: 'Innsbruck Stadt', bundesland_code: '07', is_capital: 1 },
];

// 3. Add other missing bezirke
const missingBezirke = [
  { code: 'RU', name: 'Rust',                   bundesland_code: '04', is_capital: 0 },
  { code: 'WY', name: 'Waidhofen an der Ybbs',  bundesland_code: '03', is_capital: 0 },
  { code: 'KB', name: 'Kitzbühel',              bundesland_code: '07', is_capital: 0 },
  { code: 'LA', name: 'Landeck',                bundesland_code: '07', is_capital: 0 },
  { code: 'BZ', name: 'Bludenz',                bundesland_code: '09', is_capital: 0 },
];

const allNew = [...missingCapitals, ...missingBezirke];

const insert = db.prepare('INSERT OR IGNORE INTO bezirke (code, name, bundesland_code, is_capital) VALUES (?, ?, ?, ?)');
for (const b of allNew) {
  const result = insert.run(b.code, b.name, b.bundesland_code, b.is_capital);
  if (result.changes > 0) {
    console.log('Added ' + b.code + ' | ' + b.name + ' | BL=' + b.bundesland_code + ' | capital=' + b.is_capital);
  } else {
    console.log('SKIPPED (already exists) ' + b.code + ' | ' + b.name);
  }
}

// 4. Verify: list all bezirke grouped by Bundesland with capital markers
console.log('\n\n=== VERIFICATION ===');
const bundeslaender = db.prepare('SELECT code, name FROM bundeslaender ORDER BY code').all();
let totalCount = 0;
for (const bl of bundeslaender) {
  const bezirke = db.prepare('SELECT code, name, is_capital FROM bezirke WHERE bundesland_code = ? ORDER BY code').all(bl.code);
