const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// 1. Fix incorrect is_capital flags (Statutarstädte that are NOT Landeshauptstädte)
const fixCapitals = [
  { code: 'KS', name: 'Krems Stadt' },      // NÖ - Statutarstadt, not capital
  { code: 'SE', name: 'Steyr Stadt' },       // OÖ - Statutarstadt, not capital
  { code: 'WE', name: 'Wels' },              // OÖ - Statutarstadt, not capital
  { code: 'VI', name: 'Villach Stadt' },      // Kärnten - Statutarstadt, not capital
];

for (const b of fixCapitals) {
  db.prepare('UPDATE bezirke SET is_capital = 0 WHERE code = ?').run(b.code);
  console.log('Fixed is_capital=0 for ' + b.code + ' (' + b.name + ')');
}

// 2. Add missing Landeshauptstädte
const missingCapitals = [
  { code: 'E',  name: 'Eisenstadt',      bundesland_code: '04', is_capital: 1 },
