];

const allNew = [...missingCapitals, ...missingBezirke];

const insert = db.prepare('INSERT OR IGNORE INTO bezirke (code, name, bundesland_code, is_capital) VALUES (?, ?, ?, ?)');
for (const b of allNew) {
