    console.log('Added ' + b.code + ' | ' + b.name + ' | BL=' + b.bundesland_code + ' | capital=' + b.is_capital);
  } else {
    console.log('SKIPPED (already exists) ' + b.code + ' | ' + b.name);
  }
}

// 4. Verify: list all bezirke grouped by Bundesland with capital markers
console.log('\n\n=== VERIFICATION ===');
