const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// Rename single-letter capital codes to two-letter with C suffix
const renames = [
  { oldCode: 'E', newCode: 'EC', name: 'Eisenstadt' },
  { oldCode: 'L', newCode: 'LC', name: 'Linz Stadt' },
  { oldCode: 'G', newCode: 'GC', name: 'Graz Stadt' },
  { oldCode: 'I', newCode: 'IC', name: 'Innsbruck Stadt' },
];

// Need to handle foreign keys - operators may reference these bezirk_codes
for (const r of renames) {
  // Update operators that reference the old code
  const opResult = db.prepare('UPDATE operators SET bezirk_code = ? WHERE bezirk_code = ?').run(r.newCode, r.oldCode);
  if (opResult.changes > 0) {
    console.log('  Updated ' + opResult.changes + ' operators from ' + r.oldCode + ' to ' + r.newCode);
  }

  // Update signal_reports that reference the old code
  const srResult = db.prepare('UPDATE signal_reports SET bezirk_code = ? WHERE bezirk_code = ?').run(r.newCode, r.oldCode);
  if (srResult.changes > 0) {
    console.log('  Updated ' + srResult.changes + ' signal_reports from ' + r.oldCode + ' to ' + r.newCode);
  }

  // Update the bezirk code itself
  const result = db.prepare('UPDATE bezirke SET code = ? WHERE code = ?').run(r.newCode, r.oldCode);
  if (result.changes > 0) {
    console.log('Renamed ' + r.oldCode + ' -> ' + r.newCode + ' (' + r.name + ')');
  } else {
    console.log('WARNING: ' + r.oldCode + ' not found in bezirke table');
  }
}

// Verify
console.log('\n=== Verification: All capitals ===');
const capitals = db.prepare('SELECT b.code, b.name, b.bundesland_code, bl.name as bl_name FROM bezirke b LEFT JOIN bundeslaender bl ON bl.code = b.bundesland_code WHERE b.is_capital = 1 ORDER BY b.bundesland_code').all();
for (const c of capitals) {
  console.log(c.bundesland_code + ' ' + c.bl_name + ': ' + c.code + ' ' + c.name);
}

