const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// 1. Rename Wien bezirk W -> WC
db.prepare('UPDATE operators SET bezirk_code = ? WHERE bezirk_code = ?').run('WC', 'W');
db.prepare('UPDATE bezirke SET code = ? WHERE code = ?').run('WC', 'W');
console.log('Renamed W -> WC (Wien)');

// 2. Add OE prefix to all Austrian Bundesländer names
const blUpdates = [
  ['01', 'OE1 Wien'],
  ['02', 'OE2 Salzburg'],
  ['03', 'OE3 Niederösterreich'],
  ['04', 'OE4 Burgenland'],
  ['05', 'OE5 Oberösterreich'],
  ['06', 'OE6 Steiermark'],
  ['07', 'OE7 Tirol'],
  ['08', 'OE8 Kärnten'],
  ['09', 'OE9 Vorarlberg'],
];

for (const [code, name] of blUpdates) {
  db.prepare('UPDATE bundeslaender SET name = ? WHERE code = ?').run(name, code);
  console.log('Updated ' + code + ' -> ' + name);
}

// Verify
console.log('\n=== Bundesländer ===');
const bls = db.prepare('SELECT code, name FROM bundeslaender ORDER BY code').all();
for (const bl of bls) console.log(bl.code + ' | ' + bl.name);

console.log('\n=== Capitals ===');
const caps = db.prepare('SELECT b.code, b.name, bl.name as bl_name FROM bezirke b JOIN bundeslaender bl ON bl.code = b.bundesland_code WHERE b.is_capital = 1 ORDER BY b.bundesland_code').all();
for (const c of caps) console.log(c.code + ' | ' + c.name + ' | ' + c.bl_name);

